"""Calculate salaries from cleaned attendance and task records."""

import ast
import csv
import json
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(filename: str) -> list[dict[str, str]]:
    with (DATASET / filename).open(encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def _parse_tasks(value: str) -> list[int]:
    # Some otherwise complete lists have lost an opening or closing bracket.
    value = value.strip()
    if not value.startswith("["):
        value = "[" + value
    if not value.endswith("]"):
        value += "]"
    try:
        tasks = ast.literal_eval(value)
    except (ValueError, SyntaxError):
        return []
    if not isinstance(tasks, list):
        return []
    return [task for task in tasks if type(task) is int]


def _billing_month(day: date, weekday: int) -> tuple[int, int]:
    first = day.replace(day=1)
    start = first + timedelta(days=(weekday - first.weekday()) % 7)
    if day < start:
        first = (first - timedelta(days=1)).replace(day=1)
    return first.year, first.month


def answer() -> dict[str, list[int]]:
    rates = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }

    attendance = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        # Duplicate entries have distinct IDs but identical record contents.
        key = tuple((field, value) for field, value in row.items() if field != "id")
        if key in seen:
            continue
        seen.add(key)

        pesel = row["employee_id"]
        if pesel not in rates:
            # Similar unknown IDs already have registered attendance counterparts
            # with different tasks; merging them would invent additional work.
            continue
        try:
            day = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, ArithmeticError):
            continue
        # April 31 / June 31 cannot be reliably corrected. The valid dates
        # already reproduce every recorded running salary balance exactly.
        if not hours.is_finite() or not Decimal(0) <= hours <= Decimal(24):
            continue

        # Recompute bonuses: unknown tasks and erroneous negative bonuses
        # cannot establish an entitlement beyond the supplied task catalog.
        bonus = sum(
            (task_pay.get(task, Decimal(0)) for task in _parse_tasks(row["performed_tasks"])),
            Decimal(0),
        )
        attendance.append((pesel, day, hours, bonus))

    if not attendance:
        return {pesel: [] for pesel in rates}

    weekday = min(day for _, day, _, _ in attendance).weekday()
    totals = defaultdict(Decimal)
    months = set()
    for pesel, day, hours, bonus in attendance:
        month = _billing_month(day, weekday)
        months.add(month)
        totals[pesel, month] += hours * rates[pesel] + bonus

    ordered_months = sorted(months)
    return {
        pesel: [
            int(totals[pesel, month].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
        for pesel in rates
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
